export const headers = (): Record<string, string> => {
  // console.log('api headers global.token=', global.token)
  const curLanguage = global.i18n.locale;
  const acceptLanguage =
    languageMap[curLanguage as keyof typeof languageMap] ?? String(curLanguage);
  const res: Record<string, string> = {
    'Content-Type': 'application/json',
    Authorization: global.token ? 'Bearer ' + global.token : '', // 让每个请求携带自定义token
    Cookie: global.cookie ? String(global.cookie) : '', // MFA登录成功后 global.cookie = ''
    'session-clinicId': global.curClinicData?.id ?? '',
    'Cache-Control': 'no-cache', // 這裡的Header是防止某些瀏覽器可能會緩存請求
    'Accept-Language': acceptLanguage,
  };

var token: string;
/** Set after login responses that return Set-Cookie (MFA flow). */
var cookie: string;
var i18n: I18n;
